fn zeros_like(a: &Vec<i32>) -> Vec<i32> {
    vec![0; a.len()]
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_empty() {
        let a: Vec<i32> = Vec::new();
        let z = zeros_like(&a);
        assert_eq!(z.len(), 0);
    }

    #[test]
    fn test_nonempty() {
        let a = vec![1, -2, 3, 4];
        let z = zeros_like(&a);
        assert_eq!(z.len(), a.len());
        assert!(z.iter().all(|&x| x == 0));

        // Check that adding zeros on both sides leaves the array unchanged
        let added_left: Vec<i32> = z.iter().cloned().zip(a.iter().cloned()).map(|(x, y)| x + y).collect();
        let added_right: Vec<i32> = a.iter().cloned().zip(z.iter().cloned()).map(|(x, y)| x + y).collect();
        assert_eq!(added_left, a);
        assert_eq!(added_right, a);
    }
}